1	//! The bench report: everything that turns a finished [`crate::harness::RunOutput`] into text.
2	//!
3	//! Split out of `harness.rs` so measuring and rendering stop sharing a file. The seam is
4	//! `RunOutput` itself, which the harness produces and this module consumes; nothing here feeds
5	//! back into a measurement.
6	//!
7	//! - **The band table and its summary rows** ([`print_report`]): per-quantile-band
8	//!   first/last/range/count/mean, then whole-histogram mean/stdev, the trimmed pair, the clock's
9	//!   `quantum`, and the block-replication rows.
10	//! - **The grade block**: the `env` rows grading the box across warmup and bench, over the `run`
11	//!   row grading the numbers themselves.
12	//! - **Formatting primitives** ([`fmt_commas`], [`fmt_commas_f64`], [`display_cols`],
13	//!   [`decimal_align`]) that `probe.rs` and `band_table.rs` share.
14	//!
15	//! Column alignment here assumes a terminal's uniform character cell. That assumption lives in
16	//! [`display_cols`] and nowhere else, so a renderer that measures text instead (a GUI) replaces
17	//! this module rather than editing it.
18	
19	use hdrhistogram::Histogram;
20	
21	use crate::bands::{self, BandLabels};
22	use crate::harness::{
23	    HIST_HIGH_PS, PS_PER_NS, ProbeSummary, RunCfg, RunOutput, WarmClock, WarmExit,
24	};
25	use crate::ticks;
26	
27	/// Grade-block column widths, sized to each column's widest
28	/// realistic cell so right-aligned cells always leave the
29	/// two-space gap `qualify-environment`'s parser splits on.
30	///
31	/// - label columns (`grade`, `phase`) are left-aligned
32	/// - value columns are right-aligned; a signal that does not
33	///   apply to a row prints [`GB_BLANK`]
34	const GB_GRADE_W: usize = 5;
35	/// `phase` column: `warmup` is the widest phase.
36	const GB_PHASE_W: usize = 6;
37	/// `settle` column: a journey-carrying cell with its signal letter, like
38	/// `4.84->5.24GHz 100% +-0.2% A`, is the widest.
39	const GB_SETTLE_W: usize = 27;
40	/// `worst` column: the composite letter under its header.
41	const GB_WORST_W: usize = 5;
42	/// Percentage signal cells (`spread`, `drift`): `100.00% A`.
43	const GB_PCT_W: usize = 9;
44	/// `bursts` cells: `100% B`.
45	const GB_BURSTS_W: usize = 6;
46	/// `interference` column: its own header is the widest cell.
47	const GB_INT_W: usize = 12;
48	/// `step` cells carry the timestamp: `100.00% @99.99s F`.
49	const GB_STEP_W: usize = 17;
50	/// Blank grade-block cell: this signal does not apply to this
51	/// row, or was withheld for want of points
52	/// ([`crate::gauge::MIN_SERIES_POINTS`]). A plain typeable
53	/// hyphen, not an em dash.
54	const GB_BLANK: &str = "-";
55	
56	/// `CLOCK_BOOTTIME` minus `CLOCK_MONOTONIC` elapsed divergence
57	/// (seconds) at or above which [`warn_invalid`] reports that the
58	/// system suspended during the run.
59	const SUSPEND_WARN_S: f64 = 1.0;
60	
61	/// The clock's per-sample resolution: one tick spread across the `inner` calls it brackets.
62	///
63	/// A sample times `inner` calls in one bracket, so the smallest per-call step the clock can
64	/// express is a tick divided by `inner`. It is the number that says whether a printed spread
65	/// describes the workload or the clock's lattice: a core spread well below `q` is the lattice
66	/// (rpi5-20cd's 54 MHz timer puts `q` at ~2% of the value), well above it is the workload.
67	///
68	/// - Sizing does not chase it. `pick_inner` targets framing domination, which fixes the
69	///   *relative* quantum at `tick / (RATIO * frame)`, a property of the box rather than the
70	///   bench. Chasing it instead would smear the tail linearly for precision the dither and a
71	///   few million samples already provide.
72	/// - Degenerate inputs yield 0 rather than an infinity in a report column; neither is reachable
73	///   (`pick_inner` clamps `inner` to at least 1).
74	fn quantum_ns(ticks_per_ns: f64, inner: u64) -> f64 {
75	    if ticks_per_ns <= 0.0 || inner == 0 {
76	        return 0.0;
77	    }
78	    1.0 / ticks_per_ns / inner as f64
79	}
80	
81	/// Split an environment probe series into the two stretches the environment grade scores: the
82	/// warmup's trailing window and the probes taken while the bench ran.
83	///
84	/// - `warmup` is how many leading probes came from warmup (see [`RunOutput::warmup_probes`]);
85	///   it is clamped to the series length, so a truncated series can't panic.
86	/// - The warmup side's graded tail is the last `tail_len` probes: the warm exit window the
87	///   stopping rule graded ([`RunOutput::warm_tail`]), so the letter printed is the letter the
88	///   exit saw, one computation rather than two windows that can disagree. Absorbing a ramp is
89	///   warmup's job, so the stretch before the window is deliberately ungraded.
90	/// - Grading the two separately also stops the boundary between them from reading as a step,
91	///   which a blended series invents whenever warmup starts colder than the run.
92	///
93	/// Returns `(warm, tail, during)`: the whole warmup stretch (the one
94	/// `RunOutput::warm_settle` was scored over), its tail window (what the warmup grade reads),
95	/// and the bench stretch.
96	pub(crate) fn env_stretches(
97	    probes: &[ProbeSummary],
98	    warmup: usize,
99	    tail_len: usize,
100	) -> (&[ProbeSummary], &[ProbeSummary], &[ProbeSummary]) {
101	    let (warm, during) = probes.split_at(warmup.min(probes.len()));
102	    let tail = &warm[warm.len() - tail_len.min(warm.len())..];
103	    (warm, tail, during)
104	}
105	
106	/// Print `WARNING` lines when the finished run's tail-sensitive
107	/// stats — `max` and the untrimmed mean/stdev — are poisoned:
108	///
109	/// - the system suspended during the run (clock divergence — a
110	///   mid-sample suspend inflates that sample by the sleep gap,
111	///   even under the histogram bound);
112	/// - one or more samples clamped at [`HIST_HIGH_PS`] (a wedged or
113	///   suspend-inflated sample with no detected suspend).
114	///
115	/// A few inflated samples out of millions land in the extreme
116	/// tail band: percentile boundaries and the trimmed non-tail
117	/// stats are unaffected, so the flag names what died rather than
118	/// condemning the whole report. Called at the end of
119	/// [`print_report`] so the flag is the last thing in the bench's
120	/// report, where it can't scroll out of mind. Prints one
121	/// `WARNING {name}:` header with each finding indented below it,
122	/// keeping the findings visible next to the long bench name.
123	///
124	/// Warnings are for stats that are *invalid* — poisoned by a
125	/// suspend or a clamp. The run gauge never routes here: its
126	/// signals describe the run truthfully, and much of what they
127	/// describe belongs to the workload rather than the machine.
128	pub(crate) fn warn_invalid(name: &str, hist: &Histogram<u64>, suspended_s: f64) {
129	    let mut findings: Vec<String> = Vec::new();
130	    if suspended_s >= SUSPEND_WARN_S {
131	        findings.push(format!(
132	            "system suspended ~{suspended_s:.1}s during the run; max/mean/stdev poisoned"
133	        ));
134	    }
135	    if !hist.is_empty() && hist.max() >= HIST_HIGH_PS {
136	        findings.push(format!(
137	            "sample(s) clamped at the {}s histogram bound; max/mean/stdev poisoned",
138	            HIST_HIGH_PS / 1_000_000_000_000
139	        ));
140	    }
141	    if !findings.is_empty() {
142	        println!("WARNING {name}:");
143	        for finding in &findings {
144	            println!("  {finding}");
145	        }
146	    }
147	}
148	
149	/// Format an integer with thousands separators, e.g.
150	/// `12345` → `"12,345"`.
151	pub fn fmt_commas(n: u64) -> String {
152	    let s = n.to_string();
153	    let mut result = String::new();
154	    for (i, c) in s.chars().rev().enumerate() {
155	        if i > 0 && i % 3 == 0 {
156	            result.push(',');
157	        }
158	        result.push(c);
159	    }
160	    result.chars().rev().collect()
161	}
162	
163	/// Format a step signal's ` @<time>s` suffix, empty when the
164	/// signal did not fire.
165	///
166	/// One place, used by both the environment and run grades: the two
167	/// call sites previously carried their own format strings and had
168	/// drifted to 3 and 1 decimals, printing the same quantity at
169	/// different precision on adjacent lines.
170	///
171	/// - Two decimals (10 ms) because both series locate a step to
172	///   within one block or seam, and a five-second run's
173	///   [`crate::harness::DEFAULT_BLOCKS`] blocks put that at ~50 ms. Finer would
174	///   claim resolution neither series has; coarser would lose the grid.
175	fn step_at_suffix(step_frac: f64, step_at_s: f64) -> String {
176	    if step_frac > 0.0 {
177	        format!(" @{step_at_s:.2}s")
178	    } else {
179	        String::new()
180	    }
181	}
182	
183	/// One percentage signal cell of the grade block: `value letter`
184	/// at the block's own fixed two-decimal precision (`--decimals`
185	/// governs the report's time columns, never these ratios).
186	fn pct_cell(frac: f64, letter: char) -> String {
187	    format!("{:.2}% {letter}", frac * 100.0)
188	}
189	
190	/// A signal cell that may be withheld: `render` when the grade
191	/// scored it, [`GB_BLANK`] when it did not.
192	fn withheld_cell(
193	    frac: Option<f64>,
194	    letter: Option<char>,
195	    render: impl Fn(f64, char) -> String,
196	) -> String {
197	    match (frac, letter) {
198	        (Some(f), Some(l)) => render(f, l),
199	        _ => GB_BLANK.to_string(),
200	    }
201	}
202	
203	/// A `bursts` cell: whole percent, since the signal counts
204	/// blocks and finer digits would be false precision.
205	fn burst_cell(frac: f64, letter: char) -> String {
206	    format!("{:.0}% {letter}", frac * 100.0)
207	}
208	
209	/// A `step` cell: the one signal carrying a timestamp, at the
210	/// 10 ms precision blocks can actually locate a shift to.
211	fn step_cell(step_frac: f64, step_at_s: f64, letter: char) -> String {
212	    format!(
213	        "{:.2}%{} {letter}",
214	        step_frac * 100.0,
215	        step_at_suffix(step_frac, step_at_s)
216	    )
217	}
218	
219	/// Print one grade-block line: the header or a row, nine cells
220	/// in the shared column layout the widths (`GB_*`) define.
221	fn print_grade_line(cells: [&str; 9]) {
222	    const INDENT: &str = "  ";
223	    let [
224	        grade,
225	        phase,
226	        settle,
227	        worst,
228	        spread,
229	        bursts,
230	        interference,
231	        drift,
232	        step,
233	    ] = cells;
234	    println!(
235	        "{INDENT}{grade:<GB_GRADE_W$}  {phase:<GB_PHASE_W$}  {settle:>GB_SETTLE_W$}  \
236	         {worst:>GB_WORST_W$}  {spread:>GB_PCT_W$}  {bursts:>GB_BURSTS_W$}  \
237	         {interference:>GB_INT_W$}  {drift:>GB_PCT_W$}  {step:>GB_STEP_W$}"
238	    );
239	}
240	
241	/// Format a float with `decimals` fractional digits and thousands
242	/// separators on the integer part.
243	/// Width of a rendered cell in terminal columns.
244	///
245	/// Three quantities coincide for the ASCII this report prints and diverge otherwise:
246	/// `str::len()` counts *bytes*, `{:>n$}` padding counts *chars*, and a terminal renders
247	/// *columns* (CJK is two, combining marks are zero). Counting chars is what agrees with the
248	/// padder, so a column stays square; the point of routing every measurement through one function
249	/// is that swapping in a width-aware crate later means changing this body and nothing else.
250	pub fn display_cols(s: &str) -> usize {
251	    s.chars().count()
252	}
253	
254	/// Print summary rows, a label column beside a value column aligned on the decimal point, each
255	/// value in ns: a run's `mean` through `LSC`, and a bench's rows across its runs.
256	///
257	/// - A withheld value prints a bare `-`, since a unit would dress the absence up as a number.
258	pub(crate) fn print_summary_rows(rows: &[(String, String)]) {
259	    const INDENT: &str = "  ";
260	    let label_cols = rows
261	        .iter()
262	        .map(|(l, _)| display_cols(l))
263	        .fold(0, usize::max);
264	    let int_cols = rows
265	        .iter()
266	        .map(|(_, v)| display_cols(split_decimal(v).0))
267	        .fold(0, usize::max);
268	    let frac_cols = rows
269	        .iter()
270	        .map(|(_, v)| display_cols(split_decimal(v).1))
271	        .fold(0, usize::max);
272	    for (label, v) in rows {
273	        let unit = if v == "-" { "" } else { " ns" };
274	        let line = format!(
275	            "{INDENT}{label:<label_cols$}  {}{unit}",
276	            decimal_align(v, int_cols, frac_cols),
277	        );
278	        println!("{}", line.trim_end());
279	    }
280	}
281	
282	/// Split a rendered number at its decimal point: `"15,974.399"` gives `("15,974", "399")`, and a
283	/// number without one gives an empty fraction.
284	fn split_decimal(s: &str) -> (&str, &str) {
285	    match s.find('.') {
286	        Some(i) => (&s[..i], &s[i + 1..]),
287	        None => (s, ""),
288	    }
289	}
290	
291	/// Pad a rendered number so a column of them lines up on the decimal point.
292	///
293	/// Right-justifying on the last character aligns the trailing unit but not the point, which
294	/// staggers as soon as one row carries more decimals than its neighbours: `quantum` prints at
295	/// least three (see [`quantum_ns`]) while every other row follows `--decimals`. Padding the
296	/// integer side to `int_cols` and the fraction to `frac_cols` puts every point in one column and
297	/// every following ` ns` in another.
298	///
299	/// - A value with no fraction in a column that has one is only reachable at `--decimals 0`,
300	///   where `quantum` still prints three. It pads across the point's column as well, so no row
301	///   renders a dangling `.`.
302	fn decimal_align(s: &str, int_cols: usize, frac_cols: usize) -> String {
303	    let (int, frac) = split_decimal(s);
304	    if frac_cols == 0 {
305	        return format!("{int:>int_cols$}");
306	    }
307	    if s.contains('.') {
308	        format!("{int:>int_cols$}.{frac:<frac_cols$}")
309	    } else {
310	        let blank = frac_cols + 1;
311	        format!("{int:>int_cols$}{:<blank$}", "")
312	    }
313	}
314	
315	pub fn fmt_commas_f64(n: f64, decimals: usize) -> String {
316	    let s = format!("{n:.decimals$}");
317	    let (sign, body) = match s.strip_prefix('-') {
318	        Some(rest) => ("-", rest),
319	        None => ("", s.as_str()),
320	    };
321	    let (int_part, frac_part) = match body.find('.') {
322	        Some(i) => (&body[..i], &body[i..]),
323	        None => (body, ""),
324	    };
325	    let int_num: u64 = int_part.parse().unwrap_or(0);
326	    format!("{sign}{}{frac_part}", fmt_commas(int_num))
327	}
328	
329	/// Format a claim (resolution, CI95, LSC) that must never print as a
330	/// bare zero: extend decimals from `start` until the value rounds to
331	/// a nonzero digit, capped at 3 (the ps recording floor), then print
332	/// `<0.001`. A `0.00` claim reads as "nothing to distinguish", which
333	/// is the fiction the resolution row replaced; the dash for "no claim
334	/// exists" is the caller's, not this function's.
335	pub(crate) fn fmt_claim(v: f64, start: usize) -> String {
336	    for decimals in start..=3 {
337	        if v >= 0.5 * 10f64.powi(-(decimals as i32)) {
338	            return fmt_commas_f64(v, decimals);
339	        }
340	    }
341	    "<0.001".to_string()
342	}
343	
344	/// Index of the band containing `mid_rank`, over the full boundary
345	/// ladder `bounds` (`n_bands = bounds.len() - 1`).
346	///
347	/// - Bands are **right-closed** `(lower, upper]`: a rank exactly on a
348	///   boundary falls in the band that boundary *caps* — a single
349	///   sample's mid-rank of 0.5 lands in `p50`, not `p60`. This matches
350	///   the upper-boundary row labels and the CDF reading of a
351	///   percentile (value at or below which that fraction of samples
352	///   falls). See [`print_report`] for the convention and references.
353	/// - `mid_rank` is the Hazen plotting position `(i - 0.5) / n` of the
354	///   sample's rank, computed by the caller.
355	fn band_index(mid_rank: f64, bounds: &[bands::Boundary]) -> usize {
356	    let n_bands = bounds.len() - 1;
357	    bounds[1..]
358	        .iter()
359	        .position(|b| mid_rank <= b.pct)
360	        .unwrap_or(n_bands - 1)
361	}
362	
363	/// Build the trimmed-stat range label from the populated bands
364	/// below the n2 ≡ p99 tail cut.
365	///
366	/// - Names the first..last populated band in `band_count[..trim_bands]`
367	///   by its **upper** boundary (`bounds[i + 1]`), matching the row
368	///   labels — so the label tracks the real extent of the trimmed
369	///   data rather than asserting a `min` row (never printed — rows use
370	///   upper boundaries) or an `n2` band that can be empty.
371	/// - Collapses to a single name when one band holds all the trimmed
372	///   data (`p60`, not `p60..p60`).
373	/// - Empty string when no trimmed band is populated — only with no
374	///   samples at all, where the caller's `trim` is `None` and the
375	///   label goes unused.
376	fn trim_range_label(
377	    bounds: &[bands::Boundary],
378	    band_count: &[u64],
379	    trim_bands: usize,
380	    style: BandLabels,
381	) -> String {
382	    let first = (0..trim_bands).find(|&i| band_count[i] > 0);
383	    let last = (0..trim_bands).rev().find(|&i| band_count[i] > 0);
384	    match (first, last) {
385	        (Some(f), Some(l)) if f == l => bounds[f + 1].trim_name(style).to_string(),
386	        (Some(f), Some(l)) => format!(
387	            "{}..{}",
388	            bounds[f + 1].trim_name(style),
389	            bounds[l + 1].trim_name(style),
390	        ),
391	        _ => String::new(),
392	    }
393	}
394	
395	/// Print the full bench report: header line (logfmt-style metadata),
396	/// per-band histogram, whole-histogram mean/stdev, and trimmed
397	/// mean/stdev (every band below the n2 ≡ p99 tail cut). The trimmed
398	/// rows are labeled by the span of populated non-tail bands (e.g.
399	/// `mean z4..n2`), so `min` — never a row — is not asserted and an
400	/// empty n2 band is not named; see the label derivation below.
401	///
402	/// Each histogram row is one band, labeled by its **upper**
403	/// boundary — deciles in the body (`p10` … `p90`), nines/zeros in
404	/// the tails (`zK`/`nK` = fraction 10^-K of samples below/above
405	/// the boundary) — the lower boundary being the previous printed
406	/// row (empty bands are skipped). Bands are **right-closed**
407	/// `(lower, upper]` (see [`band_index`]): a sample whose rank lands
408	/// exactly on a boundary counts in the band that boundary caps, so a
409	/// lone median sample reads `p50`, not `p60` — matching the
410	/// upper-boundary label and the CDF definition of a percentile. This
411	/// is `pandas.cut`'s `right=True` convention; the rank is the Hazen
412	/// plotting position `(i - 0.5) / n`. Label style comes from
413	/// `cfg.band_labels` and is recorded as `labels=` in the header
414	/// metadata so saved outputs are self-describing. Values are raw:
415	/// nothing is subtracted, so a column is what the apparatus
416	/// measured. The untrimmed `stdev` is the
417	/// hdrhistogram-native stdev, which includes the ms-scale outliers
418	/// in the tail band. Ends with `WARNING` lines flagging poisoned
419	/// stats when they apply — `suspended_s` comes from
420	/// [`crate::harness::run_adaptive`] (see [`warn_invalid`]).
421	pub fn print_report(name: &str, out: &RunOutput, cfg: &RunCfg) {
422	    let hist = &out.hist;
423	    let samples = out.samples;
424	    let inner = out.inner;
425	    let duration_s = out.duration_s;
426	    let suspended_s = out.suspended_s;
427	    let block_stats = &out.block_stats;
428	    // Header line: bench name + logfmt-style metadata.
429	    let total = samples * inner;
430	    // The warm cell is this run's total spend over its total
431	    // allowance: settle budget (when this run ran the process
432	    // warm) plus the cap.
433	    println!(
434	        "{name} [duration={:.1}s measured={:.1}s warm={:.2}/{:.1}s samples={} inner={} calls={} blocks={} labels={}]:",
435	        duration_s,
436	        out.measured_s,
437	        out.warm_used_s,
438	        out.warm_budget_s,
439	        fmt_commas(samples),
440	        inner,
441	        fmt_commas(total),
442	        block_stats.blocks,
443	        cfg.band_labels.as_str(),
444	    );
445	
446	    let bounds = bands::boundaries();
447	
448	    // Trim anchor: bands at or above the n2 (p99) boundary are
449	    // the "tail" — excluded from the trimmed stats no matter how
450	    // many finer tail bands subdivide them.
451	    #[allow(clippy::unwrap_used)]
452	    // OK: boundaries() always emits n2 (N_DEPTH >= 2)
453	    let trim_bands = bounds.iter().position(|b| b.zpn == "n2").unwrap();
454	
455	    let n_bands = bounds.len() - 1;
456	    let sample_count = hist.len();
457	
458	    // Accumulate per-band stats by walking recorded histogram buckets.
459	    // Each bucket is assigned to the band containing its midpoint rank.
460	    let mut band_first = vec![u64::MAX; n_bands];
461	    let mut band_last = vec![0u64; n_bands];
462	    let mut band_count = vec![0u64; n_bands];
463	    let mut band_sum = vec![0u128; n_bands];
464	
465	    let mut cumulative = 0u64;
466	    for iv in hist.iter_recorded() {
467	        let value = iv.value_iterated_to();
468	        let count = iv.count_at_value();
469	        let mid_rank = (cumulative as f64 + count as f64 / 2.0) / sample_count as f64;
470	        let idx = band_index(mid_rank, &bounds);
471	        band_first[idx] = band_first[idx].min(value);
472	        band_last[idx] = band_last[idx].max(value);
473	        band_count[idx] += count;
474	        band_sum[idx] += value as u128 * count as u128;
475	        cumulative += count;
476	    }
477	
478	    // Trimmed-stat range label, derived from the populated bands.
479	    let trim_range = trim_range_label(&bounds, &band_count, trim_bands, cfg.band_labels);
480	    let mean_trim_label = format!("mean {trim_range}");
481	    let stdev_trim_label = format!("stdev {trim_range}");
482	
483	    // Build rendered rows: (label, first, last, range, count, mean).
484	    struct BandRow {
485	        label: String,
486	        first: String,
487	        last: String,
488	        range: String,
489	        count: String,
490	        mean: String,
491	    }
492	
493	    let mut rows: Vec<BandRow> = Vec::new();
494	    for i in 0..n_bands {
495	        if band_count[i] == 0 {
496	            continue;
497	        }
498	        let mean_ns = band_sum[i] as f64 / band_count[i] as f64 / PS_PER_NS;
499	        rows.push(BandRow {
500	            label: bounds[i + 1].label(cfg.band_labels),
501	            first: fmt_commas_f64(band_first[i] as f64 / PS_PER_NS, cfg.decimals),
502	            last: fmt_commas_f64(band_last[i] as f64 / PS_PER_NS, cfg.decimals),
503	            range: fmt_commas_f64(
504	                (band_last[i] - band_first[i] + 1) as f64 / PS_PER_NS,
505	                cfg.decimals,
506	            ),
507	            count: fmt_commas(band_count[i]),
508	            mean: fmt_commas_f64(mean_ns, cfg.decimals),
509	        });
510	    }
511	
512	    // Whole-histogram and trimmed (every band below the n2 ≡ p99
513	    // tail cut) summary values, rendered before the width
514	    // pass so the widths account for them — the untrimmed stdev
515	    // is often wider than any band mean and would otherwise
516	    // overflow its column, shifting its line right.
517	    // The mean is the block series' count-weighted average, exact where
518	    // the histogram's reading is rounded to its buckets.
519	    let hist_mean_str = fmt_commas_f64(block_stats.mean_ns, cfg.decimals);
520	    let hist_stdev_str = fmt_commas_f64(hist.stdev() / PS_PER_NS, cfg.decimals);
521	
522	    let trim_count: u64 = band_count[..trim_bands].iter().sum();
523	    let trim = if trim_count > 0 {
524	        let trim_sum: u128 = band_sum[..trim_bands].iter().sum();
525	        let trim_mean = trim_sum as f64 / trim_count as f64 / PS_PER_NS;
526	
527	        // Variance: walk histogram buckets, include only non-tail bands.
528	        let mut trim_var_sum = 0.0f64;
529	        let mut trim_var_count = 0u64;
530	        let mut cum = 0u64;
531	        for iv in hist.iter_recorded() {
532	            let value = iv.value_iterated_to();
533	            let count = iv.count_at_value();
534	            let mid_rank = (cum as f64 + count as f64 / 2.0) / sample_count as f64;
535	            let idx = band_index(mid_rank, &bounds);
536	            if idx < trim_bands {
537	                let diff = value as f64 / PS_PER_NS - trim_mean;
538	                trim_var_sum += diff * diff * count as f64;
539	                trim_var_count += count;
540	            }
541	            cum += count;
542	        }
543	        let trim_stdev = if trim_var_count > 1 {
544	            (trim_var_sum / trim_var_count as f64).sqrt()
545	        } else {
546	            0.0
547	        };
548	
549	        Some((
550	            fmt_commas_f64(trim_mean, cfg.decimals),
551	            fmt_commas_f64(trim_stdev, cfg.decimals),
552	        ))
553	    } else {
554	        None
555	    };
556	
557	    // Block summary strings, rendered before the width pass like
558	    // the other summary lines. CI95 / LSC are `-` for sleepless
559	    // blocks: partitions of one continuous run cannot pretend to
560	    // be independent replicates. Present values are claims and
561	    // never print as a bare zero ([`fmt_claim`]).
562	    let (block_ci_str, block_lsc_str) = {
563	        let opt = |v: Option<f64>| match v {
564	            Some(x) => fmt_claim(x, cfg.decimals.max(1)),
565	            None => "-".to_string(),
566	        };
567	        (opt(block_stats.ci95_ns), opt(block_stats.lsc_ns))
568	    };
569	
570	    // The clock's per-sample quantum, rendered next to the spread
571	    // rows because that is where it is needed: it says whether
572	    // those rows describe the workload or the lattice. At least 3
573	    // decimals regardless of `--decimals`, since a fine quantum
574	    // renders as `0.0` at the report's default precision and zero
575	    // is the one value it must never claim.
576	    let quantum_str = fmt_commas_f64(
577	        quantum_ns(ticks::ticks_per_ns(), inner),
578	        cfg.decimals.max(3),
579	    );
580	
581	    // The resolution claim: the block-curve drift floor
582	    // ([`crate::resolution`]), the smallest delta this run can
583	    // honestly distinguish, printed on every run. A claim never
584	    // prints as a bare zero ([`fmt_claim`]): this row replaced a
585	    // fictional 0.0, and "at least 2 decimals" lost to a quiet
586	    // 7600x whose true floor sat below 5 ps.
587	    let resolution_str = match &out.resolution {
588	        Some(r) => fmt_claim(r.floor_ns, cfg.decimals.max(2)),
589	        None => "-".to_string(),
590	    };
591	
592	    // Column widths from rendered strings: band rows and the
593	    // summary lines that print in the mean column.
594	    let label_cols = rows
595	        .iter()
596	        .map(|r| display_cols(&r.label))
597	        .fold(0, usize::max);
598	    let first_cols = rows
599	        .iter()
600	        .map(|r| display_cols(&r.first))
601	        .fold(0, usize::max);
602	    let last_cols = rows
603	        .iter()
604	        .map(|r| display_cols(&r.last))
605	        .fold(0, usize::max);
606	    let range_cols = rows
607	        .iter()
608	        .map(|r| display_cols(&r.range))
609	        .fold(0, usize::max);
610	    let count_cols = rows
611	        .iter()
612	        .map(|r| display_cols(&r.count))
613	        .fold(0, usize::max);
614	    // The mean column aligns on the decimal point rather than on
615	    // its last character, so each side is measured separately
616	    // (see [`decimal_align`]). Band rows only: the summary rows
617	    // moved into their own left-aligned block below.
618	    let mean_values: Vec<&str> = rows.iter().map(|r| r.mean.as_str()).collect();
619	    let mean_int_cols = mean_values
620	        .iter()
621	        .map(|s| display_cols(split_decimal(s).0))
622	        .fold(0, usize::max);
623	    let mean_frac_cols = mean_values
624	        .iter()
625	        .map(|s| display_cols(split_decimal(s).1))
626	        .fold(0, usize::max);
627	    let mean_cols = mean_int_cols
628	        + if mean_frac_cols > 0 {
629	            mean_frac_cols + 1
630	        } else {
631	            0
632	        };
633	
634	    const INDENT: &str = "  ";
635	    const GAP: &str = "    ";
636	
637	    // Header row. Each label right-justifies to the last
638	    // character of its column's ` ns` unit; `count` is unitless
639	    // and right-justifies to its digits.
640	    const UNIT: usize = " ns".len();
641	    let first_col = INDENT.len() + label_cols + 1 + first_cols + UNIT;
642	    let last_gap = GAP.len() + last_cols + UNIT;
643	    let range_gap = GAP.len() + range_cols + UNIT;
644	    let count_gap = GAP.len() + count_cols;
645	    let mean_gap = GAP.len() + mean_cols + UNIT;
646	    println!(
647	        "{:>first_col$}{:>last_gap$}{:>range_gap$}{:>count_gap$}{:>mean_gap$}",
648	        "first", "last", "range", "count", "mean",
649	    );
650	
651	    for r in &rows {
652	        println!(
653	            "{INDENT}{:<label_cols$} {:>first_cols$} ns{GAP}{:>last_cols$} ns{GAP}{:>range_cols$} ns{GAP}{:>count_cols$}{GAP}{} ns",
654	            r.label,
655	            r.first,
656	            r.last,
657	            r.range,
658	            r.count,
659	            decimal_align(&r.mean, mean_int_cols, mean_frac_cols),
660	        );
661	    }
662	
663	    // The summary block: labels on the left beside a
664	    // decimal-aligned value column, fenced by blank lines, rather
665	    // than values right-aligned ~80 columns away under the band
666	    // table's mean column (wink's sketch, 2026-08-20, from live
667	    // 7600x runs).
668	    let mut summary: Vec<(String, String)> = vec![
669	        ("mean".to_string(), hist_mean_str),
670	        ("stdev".to_string(), hist_stdev_str),
671	    ];
672	    if let Some((trim_mean_str, trim_stdev_str)) = trim {
673	        summary.push((mean_trim_label, trim_mean_str));
674	        summary.push((stdev_trim_label, trim_stdev_str));
675	    }
676	    summary.push(("quantum".to_string(), quantum_str));
677	    summary.push(("resolution".to_string(), resolution_str));
678	    // Named by their replicate, the block, so a row never has to say which it meant beside the
679	    // across-process `CI95 runs` and `LSC runs` a bench's runs print.
680	    summary.push(("CI95 blocks".to_string(), block_ci_str));
681	    summary.push(("LSC blocks".to_string(), block_lsc_str));
682	    println!();
683	    print_summary_rows(&summary);
684	    // The grade block: one header over three rows, `env` grading
685	    // the *box* (two stretches: did warmup end settled, did the
686	    // bench stretch stay settled) above `run` grading *these*
687	    // numbers from the run's own blocks. Each row's `worst` is
688	    // its own composite (worst signal wins), printed beside its
689	    // causes; a blank cell means the signal does not apply to
690	    // that row, which is the env/run signal mapping made
691	    // visible. Reported, never warned on — see [`crate::gauge`].
692	    let (warm, tail, during) = env_stretches(&out.probes, out.warmup_probes, out.warm_tail);
693	    let warm_grade = crate::gauge::EnvGrade::from_probes(tail);
694	    let bench_grade = crate::gauge::EnvGrade::from_probes(during);
695	    let run_grade = crate::gauge::RunGrade::from_blocks(&out.blocks);
696	    if warm_grade.is_some() || bench_grade.is_some() || run_grade.is_some() {
697	        println!();
698	        print_grade_line([
699	            "grade",
700	            "phase",
701	            "settle",
702	            "worst",
703	            "spread",
704	            "bursts",
705	            "interference",
706	            "drift",
707	            "step",
708	        ]);
709	    }
710	    // The settle cell rides the warmup row because it describes that stretch alone: the
711	    // ramp the tail window now sits after. The cell answers by exit verdict: a settled
712	    // exit reports the journey and the settled share (RunOutput::warm_settle, scored in
713	    // the harness while the clock series was alive), an unstable exit reports the
714	    // journey still under way and the reserved 0%, and an uncertified warm says so
715	    // instead of a number.
716	    let settled = match out.warm_exit {
717	        WarmExit::Uncertified => "uncertified".to_string(),
718	        // An unstable exit is the settle scan's Never with the journey it was still on;
719	        // the plain form is the defensive fallback should the two ever disagree.
720	        WarmExit::Unstable => match out.warm_settle {
721	            Some(s @ crate::gauge::Settle::Never { .. }) => s.to_string(),
722	            _ => "0%".to_string(),
723	        },
724	        WarmExit::Settled => match out.warm_settle {
725	            Some(s) => s.to_string(),
726	            None => GB_BLANK.to_string(),
727	        },
728	    };
729	    // The settle cell is a graded signal like the rest: its letter prints beside its value
730	    // (crate::gauge::settle_letter) and folds into the warmup row's worst below, so a
731	    // buzzer-beater settle reads D and a never-settled warmup reads F outright.
732	    let settle_l = match (out.warm_exit, out.warm_settle) {
733	        (WarmExit::Uncertified, _) => None,
734	        (WarmExit::Unstable, None) => Some('F'),
735	        (_, Some(s)) => Some(crate::gauge::settle_letter(&s)),
736	        (_, None) => None,
737	    };
738	    let settled = match settle_l {
739	        Some(l) => format!("{settled} {l}"),
740	        None => settled,
741	    };
742	    for (phase, grade, settle_cell) in [
743	        ("warmup", &warm_grade, settled.as_str()),
744	        ("bench", &bench_grade, GB_BLANK),
745	    ] {
746	        if let Some(g) = grade {
747	            let [sl_spread, sl_int, sl_drift, sl_step] = g.signal_letters();
748	            let worst = match (phase, settle_l) {
749	                ("warmup", Some(l)) => g.letter.max(l),
750	                _ => g.letter,
751	            };
752	            // Spread and interference are always scored; the movement
753	            // signals are withheld on a short stretch.
754	            let spread = sl_spread.map_or(GB_BLANK.to_string(), |l| pct_cell(g.spread_frac, l));
755	            let interference =
756	                sl_int.map_or(GB_BLANK.to_string(), |l| pct_cell(g.interference_frac, l));
757	            print_grade_line([
758	                "env",
759	                phase,
760	                settle_cell,
761	                &worst.to_string(),
762	                &spread,
763	                GB_BLANK,
764	                &interference,
765	                &withheld_cell(g.drift_frac, sl_drift, pct_cell),
766	                &withheld_cell(g.step_frac, sl_step, |f, l| step_cell(f, g.step_at_s, l)),
767	            ]);
768	        }
769	    }
770	    if let Some(g) = run_grade {
771	        let [sl_int, sl_burst, sl_drift, sl_step] = g.signal_letters();
772	        let interference =
773	            sl_int.map_or(GB_BLANK.to_string(), |l| pct_cell(g.interference_frac, l));
774	        print_grade_line([
775	            "run",
776	            "all",
777	            GB_BLANK,
778	            &g.letter.to_string(),
779	            GB_BLANK,
780	            &withheld_cell(g.burst_frac, sl_burst, burst_cell),
781	            &interference,
782	            &withheld_cell(g.drift_frac, sl_drift, pct_cell),
783	            &withheld_cell(g.step_frac, sl_step, |f, l| step_cell(f, g.step_at_s, l)),
784	        ]);
785	    }
786	    // A run below the suggested block count says so, once, after
787	    // the grades it withheld: the `-` cells above are this line's
788	    // cause, and the number to change is named.
789	    if (block_stats.blocks as usize) < crate::gauge::MIN_SERIES_POINTS {
790	        println!();
791	        println!(
792	            "{INDENT}Note: blocks={}; {} is the suggested minimum, and {} gives the \
793	             resolution curve a second level",
794	            block_stats.blocks,
795	            crate::gauge::MIN_SERIES_POINTS,
796	            2 * crate::resolution::MIN_GROUPS,
797	        );
798	    }
799	    // A run whose blocks the time cap cut says so: its sizing estimate did not hold, the
800	    // counts are unequal, and CI95 / LSC treat the short blocks as full replicates.
801	    if out.blocks_cut > 0 {
802	        println!();
803	        println!(
804	            "{INDENT}Note: {} of {} blocks hit their time cap ({}x their budget share) before \
805	             their sample count; the bench ran slower than its warmup, so CI95 and LSC are \
806	             approximate",
807	            out.blocks_cut,
808	            block_stats.blocks,
809	            crate::harness::BLOCK_TIME_CAP_MULT,
810	        );
811	    }
812	    // The complete warmup picture under -v: the per-probe table with the ramp's
813	    // shape, and where the exit window began.
814	    if log::log_enabled!(log::Level::Debug) && !warm.is_empty() {
815	        println!();
816	        let clock_cell = match out.warm_clock {
817	            Some(WarmClock {
818	                end_mhz,
819	                max_mhz: Some(max),
820	            }) => {
821	                format!(
822	                    ", clock {end_mhz:.0}/{max:.0} MHz ({:.1}%)",
823	                    end_mhz / max * 100.0
824	                )
825	            }
826	            Some(WarmClock {
827	                end_mhz,
828	                max_mhz: None,
829	            }) => format!(", clock {end_mhz:.0} MHz"),
830	            None => String::new(),
831	        };
832	        println!(
833	            "{INDENT}warmup probes ({} total, exit {:?}, window: last {} spanning \
834	             {:.1} ms{clock_cell}):",
835	            warm.len(),
836	            out.warm_exit,
837	            tail.len(),
838	            tail_span_ms(tail),
839	        );
840	        // The clock's profile: the journey, the tick-per-step shape the stability gate saw
841	        // (settle's start is where the ticks go quiet), and the series extremes.
842	        if let Some(p) = &out.warm_clock_profile {
843	            let (journey, state) = clock_journey_state(out.warm_settle.as_ref());
844	            println!(
845	                "{INDENT}clock: {journey}{} (min {:.2} max {:.2}, {state})",
846	                p.ticks, p.min_ghz, p.max_ghz,
847	            );
848	        }
849	        println!("{INDENT}      t ms   floor ns  spread ns   over %");
850	        for p in warm {
851	            let over_pct = if p.pairs == 0 {
852	                0.0
853	            } else {
854	                p.over_pairs as f64 / p.pairs as f64 * 100.0
855	            };
856	            println!(
857	                "{INDENT}{:>10.3} {:>10.3} {:>10.3} {:>8.2}",
858	                p.t_start_s * 1e3,
859	                p.floor_q_ps as f64 / PS_PER_NS,
860	                p.spread_q_ps as f64 / PS_PER_NS,
861	                over_pct,
862	            );
863	        }
864	    }
865	    warn_invalid(name, hist, suspended_s);
866	    println!();
867	}
