869	/// The `-v` clock line's journey prefix (trailing space included, empty when the settle
870	/// verdict carries no clock) and its parenthetical state (`settled +-0.1%` / `not settled`).
871	fn clock_journey_state(settle: Option<&crate::gauge::Settle>) -> (String, String) {
872	    use crate::gauge::Settle;
873	    match settle {
874	        Some(Settle::At {
875	            start_ghz,
876	            ghz: Some(g),
877	            rating,
878	            ..
879	        }) => {
880	            let journey = match start_ghz {
881	                Some(s) => format!("{s:.2}->{g:.2}GHz "),
882	                None => format!("{g:.2}GHz "),
883	            };
884	            (
885	                journey,
886	                format!("settled{}", crate::gauge::rating_suffix(*rating)),
887	            )
888	        }
889	        Some(Settle::At { ghz: None, .. }) => (String::new(), "settled".to_string()),
890	        Some(Settle::Never {
891	            start_ghz: Some(s),
892	            end_ghz: Some(e),
893	        }) => (format!("{s:.2}->{e:.2}GHz "), "not settled".to_string()),
894	        Some(Settle::Never { .. }) => (String::new(), "not settled".to_string()),
895	        None => (String::new(), GB_BLANK.to_string()),
896	    }
897	}
