899	/// Wall span of a probe window (ms), first probe's start to the last's: the number the exit's
900	/// minimum-span rule constrains.
901	fn tail_span_ms(tail: &[ProbeSummary]) -> f64 {
902	    match (tail.first(), tail.last()) {
903	        (Some(first), Some(last)) => (last.t_start_s - first.t_start_s) * 1e3,
904	        _ => 0.0,
905	    }
906	}
