966	        // 3900X TSC at 3.792855 ticks/ns, same `inner`: ~70x finer, and invisible in a report.
967	        let q = quantum_ns(3.792855, 23);
968	        assert!((q - 0.0115).abs() < 0.0001, "got {q}");
969	    }
970	
971	    #[test]
972	    fn quantum_guards_degenerate_inputs() {
973	        assert_eq!(quantum_ns(0.0, 23), 0.0);
974	        assert_eq!(quantum_ns(3.792855, 0), 0.0);
975	    }
976	
977	    #[test]
978	    fn env_stretches_survives_a_short_series() {
979	        // `--no-env-probe` leaves only warmup probes, and fewer of them than the
980	        // recorded tail claims.
981	        let probes: Vec<ProbeSummary> = (0..3).map(|i| probe(i as f64 * 0.001, 24_000)).collect();
982	        let (warm, tail, during) = env_stretches(&probes, 16, 16);
983	        assert_eq!(warm.len(), 3);
984	        assert_eq!(tail.len(), 3);
985	        assert!(during.is_empty());
986	    }
987	
988	    /// A `band_count` vec (len = n_bands) with the given band
989	    /// indices marked populated.
990	    fn counts(n_bands: usize, populated: &[usize]) -> Vec<u64> {
991	        let mut c = vec![0u64; n_bands];
992	        for &i in populated {
993	            c[i] = 1;
994	        }
995	        c
996	    }
997	
998	    #[test]
999	    fn trim_range_label_spans_populated_bands() {
1000	        let bounds = bands::boundaries();
1001	        let n_bands = bounds.len() - 1;
1002	        // OK: boundaries() always emits n2 (N_DEPTH >= 2)
1003	        let trim_bands = bounds.iter().position(|b| b.zpn == "n2").unwrap();
1004	
1005	        // Full range: first band (label z4) through the n2 band.
1006	        let c = counts(n_bands, &[0, 5, trim_bands - 1]);
1007	        assert_eq!(
1008	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Zpn),
1009	            "z4..n2"
1010	        );
1011	        assert_eq!(
1012	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Both),
1013	            "z4..n2"
1014	        );
1015	        assert_eq!(
1016	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Frac),
1017	            "0.000_1..0.99"
1018	        );
1019	
1020	        // n2 band empty: upper end is the last populated band (p90).
1021	        let c = counts(n_bands, &[0, 11]);
1022	        assert_eq!(
1023	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Zpn),
1024	            "z4..p90"
1025	        );
1026	
1027	        // One populated band collapses to a single name.
1028	        let c = counts(n_bands, &[8]);
1029	        assert_eq!(
1030	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Zpn),
1031	            "p60"
1032	        );
1033	
1034	        // No populated trimmed band yields an empty label (unused).
1035	        let c = counts(n_bands, &[]);
1036	        assert_eq!(
1037	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Zpn),
1038	            ""
1039	        );
1040	    }
1041	
1042	    #[test]
1043	    fn band_index_right_closed_on_boundary() {
1044	        let bounds = bands::boundaries();
1045	        // Label of the band `mid_rank` falls in (bands labeled by
1046	        // upper boundary → bounds[idx + 1]).
1047	        let label = |r: f64| bounds[band_index(r, &bounds) + 1].zpn.as_str();
1048	
1049	        // Right-closed: a rank exactly on a boundary lands in the band
1050	        // that boundary caps, not the next one up.
1051	        assert_eq!(label(0.5), "p50"); // single-sample mid-rank
1052	        assert_eq!(label(0.4), "p40"); // exactly the p40 boundary
1053	        assert_eq!(label(0.99), "n2"); // exactly p99 → last non-tail band
1054	        assert_eq!(label(0.01), "z2"); // exactly the z2 boundary
1055	
1056	        // Strictly-interior ranks are unaffected by the closed end.
1057	        assert_eq!(label(0.45), "p50");
1058	        assert_eq!(label(0.55), "p60");
1059	        assert_eq!(label(0.05), "p10");
1060	    }
1061	}
